import subprocess
import configparser
import sys

def load_and_execute_config(config_path):
    config = configparser.ConfigParser()
    config.read(config_path)

    if 'setup' not in config:
        print("No setup section found")
        return

    for key, command in config['setup'].items():
        print(f"Executing {key}...")
        # Run the command directly from the config file
        result = subprocess.run(command, shell=True, capture_output=True, text=True)

        if result.returncode != 0:
            print(f"Error running {key}: {result.stderr}")
        else:
            print(f"Success: {result.stdout}")

if __name__ == "__main__":
    config_file = "/etc/deployment/setup.cfg"
    if len(sys.argv) > 1:
        config_file = sys.argv[1]
    load_and_execute_config(config_file)
